# =============================================================================# SETUP WINDOWS TASK SCHEDULER - SIMPEG BACKUP OTOMATIS# Jalankan script ini SEKALI sebagai Administrator# Klik kanan PowerShell -> "Run as Administrator" -> jalankan script ini# =============================================================================Write-Host "================================================" -ForegroundColor CyanWrite-Host " SETUP TASK SCHEDULER - SIMPEG BACKUP OTOMATIS" -ForegroundColor CyanWrite-Host "================================================" -ForegroundColor CyanWrite-Host ""$ScriptDir = "C:\Users\OPAC\Documents\GitHub\simpeg-app\scripts"# --- Buat direktori backup ---$dirs = @(    "C:\simpeg-backup\db",    "C:\simpeg-backup\logs")foreach ($dir in $dirs) {    if (-not (Test-Path $dir)) {        New-Item -ItemType Directory -Path $dir -Force | Out-Null        Write-Host "[OK] Dibuat folder: $dir" -ForegroundColor Green    } else {        Write-Host "[SKIP] Folder sudah ada: $dir" -ForegroundColor Yellow    }}Write-Host ""# =============================================================================# TASK 1: Backup Database - Setiap hari jam 02:00# =============================================================================$task1Name    = "SimpegBackupDatabase"$task1Script  = "$ScriptDir\backup-db.ps1"$task1Action  = New-ScheduledTaskAction `    -Execute "powershell.exe" `    -Argument "-NonInteractive -NoProfile -ExecutionPolicy Bypass -File `"$task1Script`""$task1Trigger = New-ScheduledTaskTrigger -Daily -At "02:00"$task1Settings = New-ScheduledTaskSettingsSet `    -ExecutionTimeLimit (New-TimeSpan -Hours 1) `    -RestartCount 3 `    -RestartInterval (New-TimeSpan -Minutes 5) `    -StartWhenAvailable# Hapus task lama jika adaif (Get-ScheduledTask -TaskName $task1Name -ErrorAction SilentlyContinue) {    Unregister-ScheduledTask -TaskName $task1Name -Confirm:$false    Write-Host "[UPDATE] Task lama '$task1Name' dihapus." -ForegroundColor Yellow}Register-ScheduledTask `    -TaskName $task1Name `    -Action $task1Action `    -Trigger $task1Trigger `    -Settings $task1Settings `    -Description "Backup otomatis database SIMPEG setiap hari jam 02:00" `    -RunLevel Highest | Out-NullWrite-Host "[OK] Task dibuat: $task1Name (setiap hari 02:00)" -ForegroundColor Green# =============================================================================# TASK 2: Sync ke Google Drive - Setiap hari jam 03:00# =============================================================================$task2Name    = "SimpegSyncGoogleDrive"$task2Script  = "$ScriptDir\sync-gdrive.ps1"$task2Action  = New-ScheduledTaskAction `    -Execute "powershell.exe" `    -Argument "-NonInteractive -NoProfile -ExecutionPolicy Bypass -File `"$task2Script`""$task2Trigger = New-ScheduledTaskTrigger -Daily -At "03:00"$task2Settings = New-ScheduledTaskSettingsSet `    -ExecutionTimeLimit (New-TimeSpan -Hours 2) `    -RestartCount 3 `    -RestartInterval (New-TimeSpan -Minutes 10) `    -StartWhenAvailable# Hapus task lama jika adaif (Get-ScheduledTask -TaskName $task2Name -ErrorAction SilentlyContinue) {    Unregister-ScheduledTask -TaskName $task2Name -Confirm:$false    Write-Host "[UPDATE] Task lama '$task2Name' dihapus." -ForegroundColor Yellow}Register-ScheduledTask `    -TaskName $task2Name `    -Action $task2Action `    -Trigger $task2Trigger `    -Settings $task2Settings `    -Description "Sync backup SIMPEG ke Google Drive setiap hari jam 03:00" `    -RunLevel Highest | Out-NullWrite-Host "[OK] Task dibuat: $task2Name (setiap hari 03:00)" -ForegroundColor GreenWrite-Host ""Write-Host "================================================" -ForegroundColor CyanWrite-Host " SEMUA TASK SCHEDULER BERHASIL DIBUAT!" -ForegroundColor GreenWrite-Host "================================================" -ForegroundColor CyanWrite-Host ""Write-Host "Cek di: Task Scheduler -> Task Scheduler Library" -ForegroundColor WhiteWrite-Host "  - SimpegBackupDatabase  : jam 02:00 setiap hari" -ForegroundColor WhiteWrite-Host "  - SimpegSyncGoogleDrive : jam 03:00 setiap hari" -ForegroundColor White